lemma.raw:
{\small \label{lem:att1} Let Assumptions \ref{ass:irrev}, \ref{ass:iid},
\ref{ass:anticipation}, \ref{ass:common-trends}, and \ref{ass:overlap} hold.
Then, for all $g$ and $t$ such that $g\in\mathcal{G}_{\delta}$, $t\in\left\{
2,\dots\mathcal{T-\delta}\right\}  $ and $t\geq g-\delta$,
\[
ATT_{X}(g,t)=\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,G_{g}=1]-\mathbb{E}
[Y_{t}-Y_{g-\delta-1}|X,C=1]\ a.s..
\]
}

{\small \label{lem:att1-ny} Let Assumptions \ref{ass:irrev}, \ref{ass:iid},
\ref{ass:anticipation}, \ref{ass:common-trends-ny} and \ref{ass:overlap} hold.
Then, for all $g$ and $t$ such that $g\in\mathcal{G}_{\delta}$, $t\in\left\{
2,\dots\mathcal{T-\delta}\right\}  $ with $g-\delta \le t < \bar{g}$
\[
ATT_{X}(g,t)=\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,G_{g}=1]-\mathbb{E}
[Y_{t}-Y_{g-\delta-1}|X,D_{t+\delta}=0,G_{g}=0]\ a.s..
\]
}

