{\small \noindent\textbf{Proof of Lemma \ref{lem:att1-ny}:} The proof follows
similar steps as the proof of Lemma \textbf{\ref{lem:att1}}. Taking all
equalities to hold almost surely (a.s.), we have that
\begin{align*}
ATT_{X}(g,t)  &  =\mathbb{E}[Y_{t}\left(  g\right)  -Y_{g-\delta-1}\left(
0\right)  |X,G_{g}=1]-\mathbb{E}[Y_{t}\left(  0\right)  -Y_{g-\delta-1}\left(
0\right)  |X,G_{g}=1]\\
&  =\mathbb{E}[Y_{t}\left(  g\right)  -Y_{g-\delta-1}\left(  0\right)
|X,G_{g}=1]-\sum_{\ell=0}^{t-g-\delta}\mathbb{E}[\Delta Y_{t-\ell}\left(
0\right)  |X,G_{g}=1]\\
&  =\mathbb{E}[Y_{t}\left(  g\right)  -Y_{g-\delta-1}\left(  0\right)
|X,G_{g}=1]-\sum_{\ell=0}^{t-g-\delta}\mathbb{E}[\Delta Y_{t-\ell}\left(
0\right)  |X,D_{t+\delta}=0,G_{g}=0]\\
&  =\mathbb{E}[Y_{t}\left(  g\right)  -Y_{g-\delta-1}\left(  0\right)
|X,G_{g}=1]-\mathbb{E}[Y_{t}\left(  0\right)  -Y_{g-\delta-1}\left(  0\right)
|X,D_{t+\delta}=0,G_{g}=0]\\
&  =\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,G_{g}=1]-\mathbb{E}[Y_{t}-Y_{g-\delta
-1}|X,D_{t+\delta}=0,G_{g}=0]
\end{align*}
where the first equality follows from adding and subtracting $\mathbb{E}
[Y_{g-\delta-1}\left(  0\right)  |X,G_{g}=1]$, the second equality from simple
algebra, the third equality by Assumption \ref{ass:common-trends-ny} with
$s=t+\delta$, the fourth equality by simple algebra, and the last equality from
(\ref{eq:observational}) and Assumption \ref{ass:anticipation}. $\square
\bigskip$ }

{\small Now, we are ready to proceed with the proofs of our main
theorems.\bigskip}

{\small \noindent\textbf{Proof of Theorem \ref{thm:att}:} }

{\small \textbf{Part 1: Identification when Assumption \ref{ass:common-trends}
is invoked. } }

{\small In this case, given the result in Lemma \ref{lem:att1},
\begin{align*}
ATT(g,t)  &  =\mathbb{E}[ATT_{X}(g,t)|G_{g}=1]\\
&  =\mathbb{E}\left[  \left.  \left(  \mathbb{E}[Y_{t}-Y_{g-\delta-1}
|X,G_{g}=1]-\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,C=1]\right)  \right\vert
G_{g}=1\right] \\
&  =\mathbb{E}[Y_{t}-Y_{g-\delta-1}|G_{g}=1]-\mathbb{E}\left[
\underset{=m_{g,t,\delta}^{nev}\left(  X\right)  }{\underbrace{\mathbb{E}
[Y_{t}-Y_{g-\delta-1}|X,C=1]}}|G_{g}=1\right] \\
&  =\mathbb{E}\left[  \frac{G_{g}}{\mathbb{E}\left[  G_{g}\right]  }\left(
Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  X\right)  \right)  \right]  .
\end{align*}
Hence, we have that $ATT(g,t)=ATT_{or}^{nev}\left(  g,t;\delta\right)  .$ }

{\small Next, to show that $ATT(g,t)=ATT_{ipw}^{nev}\left(  g,t;\delta\right)
$, it suffices to show that
\begin{equation}
\frac{\mathbb{E}\left[  \dfrac{p_{g}\left(  X\right)  C}{(1-p_{g}(X))}
(Y_{t}-Y_{g-\delta-1})\right]  }{\mathbb{E}\left[  \dfrac{p_{g}\left(
X\right)  C}{(1-p_{g}(X))}\right]  }=\frac{\mathbb{E}\left[  G_{g}
\cdot\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,C=1]\right]  }{\mathbb{E}\left[
G_{g}\right]  }. \label{eqn:ipw}
\end{equation}
Towards this end, by noticing that
\begin{equation}
p_{g}\left(  X\right)  =\frac{\mathbb{E}\left[  G_{g}|X\right]  }
{\mathbb{E}\left[  G_{g}+C|X\right]  },~1-p_{g}\left(  X\right)
=\frac{\mathbb{E}\left[  C|X\right]  }{\mathbb{E}\left[  G_{g}+C|X\right]  },
\label{eqn:pscore_nev}
\end{equation}
it follows that
\begin{align}
\mathbb{E}\left[  \dfrac{p_{g}\left(  X\right)  C}{1-p_{g}(X)}\right]   &
=\mathbb{E}\left[  \dfrac{\mathbb{E}\left[  G_{g}|X\right]  C}
{\mathbb{E}\left[  C|X\right]  }\right] \nonumber\\
&  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[  G_{g}|X\right]  \mathbb{E}
\left[  C|X\right]  }{\mathbb{E}\left[  C|X\right]  }\right] \nonumber\\
&  =\mathbb{E}\left[  \mathbb{E}\left[  G_{g}|X\right]  \right] \nonumber\\
&  =\mathbb{E}\left[  G_{g}\right]  . \label{eqn:Hajek}
\end{align}
Next, by exploiting (\ref{eqn:pscore_nev}) and applying the law of iterated
expectations, we have that
\begin{align*}
\mathbb{E}\left[  \dfrac{p_{g}\left(  X\right)  C}{(1-p_{g}(X))}
(Y_{t}-Y_{g-\delta-1})\right]   &  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[
G_{g}|X\right]  C}{\mathbb{E}\left[  C|X\right]  }(Y_{t}-Y_{g-\delta
-1})\right] \\
&  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[  G_{g}|X\right]  }
{\mathbb{E}\left[  C|X\right]  }\mathbb{E}\left[  \left.  C\cdot
(Y_{t}-Y_{g-\delta-1})\right\vert X\right]  \right] \\
&  =\mathbb{E}\left[  \mathbb{E}\left[  G_{g}|X\right]  \cdot\mathbb{E}\left[
\left.  (Y_{t}-Y_{g-\delta-1})\right\vert X,C=1\right]  \right] \\
&  =\mathbb{E}\left[  G_{g}\cdot\mathbb{E}\left[  \left.  (Y_{t}
-Y_{g-\delta-1})\right\vert X,C=1\right]  \right]  .
\end{align*}
Thus, combined this with (\ref{eqn:Hajek}), we establish (\ref{eqn:ipw}),
implying that $ATT(g,t)=ATT_{ipw}^{nev}\left(  g,t;\delta\right)  $. }

{\small Finally, notice that
\begin{align*}
ATT_{dr}^{nev}\left(  g,t;\delta\right)   &  =\mathbb{E}\left[  \left(
\frac{G_{g}}{\mathbb{E}\left[  G_{g}\right]  }-\frac{\dfrac{p_{g}\left(
X\right)  C}{1-p_{g}\left(  X\right)  }}{\mathbb{E}\left[  \dfrac{p_{g}\left(
X\right)  C}{1-p_{g}\left(  X\right)  }\right]  }\right)  \left(
Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  X\right)  \right)  \right] \\
&  =\underset{\equiv ATT_{ipw}^{nev}\left(  g,t;\delta\right)
}{\underbrace{\mathbb{E}\left[  \left(  \frac{G_{g}}{\mathbb{E}\left[
G_{g}\right]  }-\frac{\dfrac{p_{g}\left(  X\right)  C}{1-p_{g}\left(
X\right)  }}{\mathbb{E}\left[  \dfrac{p_{g}\left(  X\right)  C}{1-p_{g}\left(
X\right)  }\right]  }\right)  \left(  Y_{t}-Y_{g-\delta-1}\right)  \right]  }
}\\
&  ~~~~~~~~~~~~~~~-\mathbb{E}\left[  \left(  \frac{G_{g}}{\mathbb{E}\left[
G_{g}\right]  }-\frac{\dfrac{p_{g}\left(  X\right)  C}{1-p_{g}\left(
X\right)  }}{\mathbb{E}\left[  \dfrac{p_{g}\left(  X\right)  C}{1-p_{g}\left(
X\right)  }\right]  }\right)  m_{g,t,\delta}^{nev}\left(  X\right)  \right] \\
&  =ATT\left(  g,t\right)  -\frac{1}{\mathbb{E}\left[  G_{g}\right]
}\mathbb{E}\left[  \left(  G_{g}-\dfrac{\mathbb{E}\left[  G_{g}|X\right]
C}{\mathbb{E}\left[  C|X\right]  }\right)  m_{g,t,\delta}^{nev}\left(
X\right)  \right] \\
&  =ATT\left(  g,t\right)  -\frac{1}{\mathbb{E}\left[  G_{g}\right]
}\mathbb{E}\left[  \left(  \mathbb{E}\left[  G_{g}|X\right]  -\mathbb{E}
\left[  G_{g}|X\right]  \right)  \cdot m_{g,t,\delta}^{nev}\left(  X\right)
\right] \\
&  =ATT\left(  g,t\right)  .
\end{align*}
where the third equality follows from $ATT_{ipw}^{nev}\left(  g,t;\delta
\right)  =ATT\left(  g,t\right)  $, (\ref{eqn:pscore_nev}) and
(\ref{eqn:Hajek}), and the fourth equality from the law of iterated
expectations.\medskip}

{\small \textbf{Part 2: Identification when Assumption
\ref{ass:common-trends-ny} is invoked. } }

{\small In this case, given the result in Lemma \ref{lem:att1-ny},
\begin{align*}
ATT(g,t)  &  =\mathbb{E}[ATT_{X}(g,t)|G_{g}=1]\\
&  =\mathbb{E}\left[  \left.  \left(  \mathbb{E}[Y_{t}-Y_{g-\delta-1}
|X,G_{g}=1]-\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,D_{t+\delta}=0,G_{g}=0]\right)
\right\vert G_{g}=1\right] \\
&  =\mathbb{E}[Y_{t}-Y_{g-\delta-1}|G_{g}=1]-\mathbb{E}\left[
\underset{=m_{g,t,\delta}^{ny}\left(  X\right)  }{\underbrace{\mathbb{E}
[Y_{t}-Y_{g-\delta-1}|X,D_{t+\delta}=0,G_{g}=0]}}|G_{g}=1\right] \\
&  =\mathbb{E}\left[  \frac{G_{g}}{\mathbb{E}\left[  G_{g}\right]  }\left(
Y_{t}-Y_{g-1-a}-m_{g,t,\delta}^{ny}\left(  X\right)  \right)  \right]  .
\end{align*}
Hence, we have that $ATT(g,t)=ATT_{or}^{ny}\left(  g,t;\delta\right)  .$ }

{\small Next, to show that $ATT(g,t)=ATT_{ipw}^{ny}\left(  g,t;\delta\right)
$, it suffices to show that
\begin{equation}
\frac{\mathbb{E}\left[  \dfrac{p_{g,t+\delta}\left(  X\right)  \left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  }{1-p_{g,t+\delta}\left(
X\right)  }(Y_{t}-Y_{g-\delta-1})\right]  }{\mathbb{E}\left[  \dfrac
{p_{g,t+\delta}\left(  X\right)  \left(  1-D_{t+\delta}\right)  \left(
1-G_{g}\right)  }{1-p_{g,t+\delta}\left(  X\right)  }\right]  }=\frac
{\mathbb{E}\left[  G_{g}\cdot\mathbb{E}[Y_{t}-Y_{g-\delta-1}|X,D_{t+\delta
}=0,G_{g}=0]\right]  }{\mathbb{E}\left[  G_{g}\right]  }. \label{eqn:ipw_ny}
\end{equation}
Towards this end, recall that $p_{g,t+\delta}(X)=P(G_{g}=1|X,G_{g}+\left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  =1)$ and also notice that 
\begin{equation}
p_{g,t+\delta}\left(  X\right)  =\frac{\mathbb{E}\left[  G_{g}|X\right]
}{\mathbb{E}\left[  G_{g}+\left(  1-D_{t+\delta}\right)  \left(
1-G_{g}\right)  |X\right]  },~1-p_{g}\left(  X\right)  =\frac{\mathbb{E}
\left[  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  |X\right]
}{\mathbb{E}\left[  G_{g}+\left(  1-D_{t+\delta}\right)  \left(
1-G_{g}\right)  |X\right]  }, \label{eqn:pscore_ny}
\end{equation}
it follows that by the law of iterated expectations,
\begin{align}
\mathbb{E}\left[  \dfrac{p_{g,t+\delta}\left(  X\right)  \left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  }{1-p_{g,t+\delta}\left(
X\right)  }\right]   &  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[
G_{g}|X\right]  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
}{\mathbb{E}\left[  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
|X\right]  }\right] \nonumber\\
&  =\mathbb{E}\left[  G_{g}\right]  . \label{eqn:hajek_ny}
\end{align}
Next, by exploiting (\ref{eqn:pscore_ny}) and applying the law of iterated
expectations, we have that
\begin{align*}
&  \mathbb{E}\left[  \dfrac{p_{g,t+\delta}\left(  X\right)  \left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  }{1-p_{g,t+\delta}\left(
X\right)  }(Y_{t}-Y_{g-\delta-1})\right] \\
&  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[  G_{g}|X\right]  \left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  }{\mathbb{E}\left[  \left(
1-D_{t+\delta}\right)  \left(  1-G_{g}\right)  |X\right]  }(Y_{t}
-Y_{g-\delta-1})\right] \\
&  =\mathbb{E}\left[  \dfrac{\mathbb{E}\left[  G_{g}|X\right]  }
{\mathbb{E}\left[  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
|X\right]  }\mathbb{E}\left[  \left.  \left(  1-D_{t+\delta}\right)  \left(
1-G_{g}\right)  \cdot(Y_{t}-Y_{g-\delta-1})\right\vert X\right]  \right] \\
&  =\mathbb{E}\left[  \mathbb{E}\left[  G_{g}|X\right]  \cdot\mathbb{E}\left[
\left.  (Y_{t}-Y_{g-\delta-1})\right\vert X,D_{t+\delta}=0,G_{g}=0\right]
\right] \\
&  =\mathbb{E}\left[  G_{g}\cdot\mathbb{E}\left[  \left.  (Y_{t}
-Y_{g-\delta-1})\right\vert X,D_{t+\delta}=0,G_{g}=0\right]  \right]  .
\end{align*}
Thus, combined this with (\ref{eqn:hajek_ny}), we establish (\ref{eqn:ipw_ny}
), implying that $ATT(g,t)=ATT_{ipw}^{ny}\left(  g,t;\delta\right)  $. }

{\small Finally, notice that
\begin{align*}
ATT_{dr}^{ny}\left(  g,t;\delta\right)   &  =\mathbb{E}\left[  \left(
\frac{G_{g}}{\mathbb{E}\left[  G_{g}\right]  }-\frac{\dfrac{p_{g,t+\delta
}\left(  X\right)  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
}{1-p_{g,t+\delta}\left(  X\right)  }}{\mathbb{E}\left[  \dfrac{p_{g,t+\delta
}\left(  X\right)  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
}{1-p_{g,t+\delta}\left(  X\right)  }\right]  }\right)  \left(  Y_{t}
-Y_{g-\delta-1}-m_{g,t,\delta}^{ny}\left(  X\right)  \right)  \right] \\
&  =ATT_{ipw}^{ny}\left(  g,t;\delta\right)  -\frac{1}{\mathbb{E}\left[
G_{g}\right]  }\mathbb{E}\left[  \left(  G_{g}-\dfrac{\mathbb{E}\left[
G_{g}|X\right]  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
}{\mathbb{E}\left[  \left(  1-D_{t+\delta}\right)  \left(  1-G_{g}\right)
|X\right]  }\right)  m_{g,t,\delta}^{ny}\left(  X\right)  \right] \\
&  =ATT\left(  g,t\right)  -\frac{1}{\mathbb{E}\left[  G_{g}\right]
}\mathbb{E}\left[  \left(  \mathbb{E}\left[  G_{g}|X\right]  -\mathbb{E}
\left[  G_{g}|X\right]  \right)  \cdot m_{g,t,\delta}^{nev}\left(  X\right)
\right] \\
&  =ATT\left(  g,t\right)  .
\end{align*}
where the second equality follows from (\ref{eqn:pscore_ny}) and
(\ref{eqn:hajek_ny}), and the third equality from $ATT_{ipw}^{nev}\left(
g,t;\delta\right)  =ATT\left(  g,t\right)  $ and the law of iterated
expectations.$\square\bigskip$ }

{\small \textbf{Proof of Theorem \ref{thm:2}: }From Theorem
\textbf{\ref{thm:att}} it follows that $ATT\left(  g,t\right)  $'s are
point-identified for all groups $g$ and time periods $t$ such that
$g\in\mathcal{G}_{\delta}$, $t\in\left\{  2,\dots\mathcal{T-\delta}\right\}  $
and $t\geq g-\delta$. For each $(g,t)$ pair, the asymptotic linear
representation of $\sqrt{n}(\widehat{ATT}_{dr}^{nev}\left(  g,t;\delta\right)
-ATT\left(  g,t\right)  )$ follows from Theorem A.1(a) of \cite{SantAnna2020},
whereas
\[
\sqrt{n}(\widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{dr,nev}
-ATT_{t\geq\left(  g-\delta\right)  })\xrightarrow{d}N(0,\mathbb{E}
[\Psi_{t\geq\left(  g-\delta\right)  }^{dr,nev}(W)\Psi_{t\geq\left(
g-\delta\right)  }^{dr,nev}(W)^{\prime}])
\]
follows from the Lindeberg--L\'{e}vy central limit theorem.$\square\bigskip$ }

{\small \noindent\textbf{Proof of Theorem \ref{thm:bootstrap}:} Note that, by
the conditional multiplier central limit theorem, see Lemma 2.9.5 in
\cite{VanderVaart1996}, as $n\rightarrow\infty$,
\begin{equation}
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\Psi_{t\geq\left(  g-\delta\right)
}^{dr,nev}(W_{i})\underset{\ast}{\overset{d}{\rightarrow}}N(0,\Sigma
),\label{eq:boot.0}
\end{equation}
where $\Sigma=\mathbb{E}[\Psi_{t\geq\left(  g-\delta\right)  }^{dr,nev}
(W)\Psi_{t\geq\left(  g-\delta\right)  }^{dr,nev}(W)^{\prime}].$ Thus, to
conclude the proof that
\[
\sqrt{n}\left(  \widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{\ast
,dr,nev}-\widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{dr,nev}\right)
\underset{\ast}{\overset{d}{\rightarrow}}N(0,\Sigma),
\]
it suffices to show that, for all $g$ and $t$ such that $g\in\mathcal{G}
_{\delta}$, $t\in\left\{  2,\dots\mathcal{T-\delta}\right\}  $ and $t\geq
g-\delta$,
\begin{equation}
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left[  \widehat{\psi}_{g,t,\delta
}^{dr,nev}(W_{i};\widehat{\kappa}_{g,t}^{nev})-\psi_{g,t,\delta}
^{dr,nev}(W_{i};\kappa_{g,t}^{\ast,nev})\right]  =o_{p^{\ast}}\left(
1\right)  ,\label{boot:needed}
\end{equation}
where $\kappa_{g,t}^{\ast,nev}=\left(  \pi_{g}^{\ast\prime},\beta_{g,t,\delta
}^{\ast,nev~\prime}\right)  ^{\prime}$ is the vector of pseudo-true
finite-dimensional parameters. }

{\small Towards this end, recall that
\[
\widehat{\psi}_{g,t,\delta}^{dr,nev}(W_{i};\widehat{\kappa}_{g,t}
^{nev})=\widehat{\psi}_{g,t,\delta}^{treat,nev}(W_{i};\widehat{\beta
}_{g,t,\delta}^{nev})-\widehat{\psi}_{g,t,\delta}^{comp,nev}(W_{i}
;\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta}^{nev})-\widehat{\psi
}_{g,t,\delta}^{est,nev}(W_{i};\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta
}^{nev})
\]
where
\begin{align*}
\widehat{\psi}_{g,t,\delta}^{treat,nev}(W;\widehat{\beta}_{g,t,\delta}^{nev})
&  =\widehat{w}_{g}^{treat}\cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta
}^{nev}\left(  \widehat{\beta}_{g,t,\delta}^{nev}\right)  \right) \\
&  ~~~~~~~~-\widehat{w}_{g}^{treat}\cdot\mathbb{E}_{n}\left[  \widehat{w}
_{g}^{treat}\cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(
\widehat{\beta}_{g,t,\delta}^{nev}\right)  \right)  \right]  ,\\
\widehat{\psi}_{g,t,\delta}^{comp,nev}(W;\widehat{\pi}_{g},\widehat{\beta
}_{g,t,\delta}^{nev})  &  =\widehat{w}_{g}^{comp,nev}\left(  \widehat{\pi}
_{g}\right)  \cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(
\widehat{\beta}_{g,t,\delta}^{nev}\right)  \right) \\
&  ~~~~~~~~-\widehat{w}_{g}^{comp}\left(  \widehat{\pi}_{g}\right)
\cdot\mathbb{E}_{n}\left[  w_{g}^{comp}\left(  \widehat{\pi}_{g}\right)
\cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  \widehat{\beta
}_{g,t,\delta}^{nev}\right)  \right)  \right]  ,\\
\widehat{\psi}_{g,t}^{est,nev}(W;\widehat{\pi}_{g},\widehat{\beta}
_{g,t,\delta}^{nev})  &  =l_{g,t}^{or,nev}\left(  \widehat{\beta}_{g,t,\delta
}^{nev}\right)  ^{\prime}\cdot\widehat{M}_{g,t,\delta}^{dr,nev,1}
+l_{g}^{ps,nev}\left(  \widehat{\pi}_{g}\right)  ^{\prime}\cdot\widehat{M}
_{g,t,\delta}^{dr,nev,2},
\end{align*}
with
\[
\widehat{w}_{g}^{treat}=\frac{G_{g}}{\mathbb{E}_{n}\left[  G_{g}\right]
},~~~~\widehat{w}_{g}^{comp,nev}\left(  \widehat{\pi}_{g}\right)
=\frac{\dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)
C}{1-\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  }}{\mathbb{E}
_{n}\left[  \dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)
C}{1-\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]  },
\]
and
\begin{align*}
\widehat{M}_{g,t,\delta}^{dr,nev,1}  &  =\mathbb{E}_{n}\left[  \left(
\widehat{w}_{g}^{treat}-\widehat{w}_{g}^{comp,nev}\left(  \widehat{\pi}_{g}\right)
\right)  \cdot\dot{m}_{g,t,\delta}^{nev}\left(  \widehat{\beta}_{g,t,\delta
}^{nev}\right)  \right]  ,\\
\widehat{M}_{g,t,\delta}^{dr,nev,2}  &  =\mathbb{E}_{n}\left[  \widehat{\alpha
}_{g}^{ps,nev}\left(  \widehat{\pi}_{g}\right)  \cdot\left(  Y_{t}
-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  \widehat{\beta}_{g,t,\delta}
^{nev}\right)  \right)  \cdot\dot{p}_{g}\left(  \widehat{\pi}_{g}\right)
\right] \\
&  ~~~~~~~~-\mathbb{E}_{n}\left[  \widehat{\alpha}_{g}^{ps,nev}\left(
\widehat{\pi}_{g}\right)  \cdot\widehat{w}_{g}^{comp,nev}\left(  \widehat{\pi
}_{g}\right)  \cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(
\widehat{\beta}_{g,t,\delta}^{nev}\right)  \right)  \cdot\dot{p}_{g}\left(
\widehat{\pi}_{g}\right)  \right]  ,\\
\widehat{\alpha}_{g}^{ps,nev}\left(  \widehat{\pi}_{g}\right)   &  =\left.
\dfrac{C}{\left(  1-p_{g}\left(  X;\widehat{\pi}_{g}\right)  \right)  ^{2}
}\right/  \mathbb{E}_{n}\left[  \dfrac{p_{g}\left(  X;\widehat{\pi}
_{g}\right)  C}{1-p_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]  .
\end{align*}
}

{\small We first show that
\begin{equation}
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left(  \widehat{\psi}_{g,t,\delta
}^{treat,nev}(W_{i};\widehat{\beta}_{g,t,\delta}^{nev})-\psi_{g,t,\delta
}^{treat,nev}(W_{i};\beta_{g,t,\delta}^{\ast,nev})\right)  =o_{p^{\ast}
}\left(  1\right)  . \label{boot:treated}
\end{equation}
Using the mean-value theorem, we write
\begin{align*}
&  \frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{\psi}_{g,t,\delta
}^{treat,nev}(W_{i};\widehat{\beta}_{g,t,\delta}^{nev})\\
&  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{w}_{g,i}^{treat}
\cdot\left(  Y_{i,t}-Y_{i,g-\delta-1}-m_{g,t,\delta}^{nev}\left(  W_{i}
;\beta_{g,t,\delta}^{\ast,nev}\right)  \right) \\
&  -\sqrt{n}\left(  \widehat{\beta}_{g,t,\delta}^{nev}-\beta_{g,t,\delta
}^{\ast,nev}\right)  ^{\prime}\frac{1}{n}\sum_{i=1}^{n}V_{i}\cdot
\widehat{w}_{g,i}^{treat}\cdot\dot{m}_{g,t,\delta}^{nev}\left(  W_{i}
;\bar{\beta}_{g,t,\delta}^{nev}\right) \\
&  -\mathbb{E}_{n}\left[  \widehat{w}_{g}^{treat}\cdot\left(  Y_{t}
-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  \widehat{\beta}_{g,t,\delta}
^{nev}\right)  \right)  \right]  \frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}
\cdot\widehat{w}_{g,i}^{treat}\\
&  =\widehat{I}_{g,t,\delta}^{1,treat}-\widehat{I}_{g,t,\delta}^{2,treat}
-\widehat{I}_{g,t,\delta}^{3,treat},
\end{align*}
where $\bar{\beta}_{g,t,\delta}^{nev}$ is an intermediate point that satisfies
$\left\vert \bar{\beta}_{g,t,\delta}^{nev}-\beta_{g,t,\delta}^{\ast
,nev}\right\vert \leq\left\vert \widehat{\beta}_{g,t,\delta}^{nev}
-\beta_{g,t,\delta}^{\ast,nev}\right\vert $ a.s.. From the strong law of large
numbers and the fact that $V$ is mean zero, independent of $W$, it follows
that
\begin{align*}
\widehat{I}_{g,t,\delta}^{1,treat}  &  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}
V_{i}\cdot w_{g,i}^{treat}\cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta
}^{nev}\left(  W_{i};\beta_{g,t,\delta}^{\ast,nev}\right)  \right)
+o_{p^{\ast}}\left(  1\right) \\
\widehat{I}_{g,t,\delta}^{3,treat}  &  =\frac{1}{\sqrt{n}}~\sum_{i=1}^{n}
V_{i}\cdot w_{g,i}^{treat}\cdot\mathbb{E}\left[  w_{g}^{treat}\cdot\left(
Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  \beta_{g,t,\delta}^{\ast
,nev}\right)  \right)  \right]  +o_{p^{\ast}}\left(  1\right)
\end{align*}
Similarly, from Assumptions \ref{ass:parametric} and \ref{ass:integrabilitity}
, and the strong law of large numbers, we conclude that $\widehat{I}
_{g,t,\delta}^{2,treat}=o_{p^{\ast}}\left(  1\right)  $. Now
(\ref{boot:treated}) follows from combining these results. }

{\small Next, we show
\begin{equation}
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left(  \widehat{\psi}_{g,t,\delta
}^{comp,nev}(W_{i};\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta}^{nev}
)-\psi_{g,t,\delta}^{comp,nev}(W_{i};\pi_{g}^{\ast},\beta_{g,t,\delta}
^{\ast,nev})\right)  =o_{p^{\ast}}\left(  1\right)  . \label{boot:comp}
\end{equation}
Again, by the mean value theorem, we write
\begin{align*}
&  \frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{\psi}_{g,t,\delta
}^{comp,nev}(W_{i};\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta}^{nev})\\
&  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{w}_{g}^{comp,nev}
\left(  W_{i};\widehat{\pi}_{g}\right)  \cdot\left(  Y_{i,t}-Y_{i,g-\delta
-1}-m_{g,t,\delta}^{nev}\left(  W_{i};\beta_{g,t,\delta}^{\ast,nev}\right)
\right) \\
&  -\sqrt{n}\left(  \widehat{\beta}_{g,t,\delta}^{nev}-\beta_{g,t,\delta
}^{\ast,nev}\right)  ^{\prime}\frac{1}{n}\sum_{i=1}^{n}V_{i}\cdot
\widehat{w}_{g}^{comp,nev}\left(  W_{i};\widehat{\pi}_{g}\right)  \cdot\dot
{m}_{g,t,\delta}^{nev}\left(  W_{i};\bar{\beta}_{g,t,\delta}^{nev}\right) \\
&  -\mathbb{E}_{n}\left[  \widehat{w}_{g}^{comp,nev}\left(  \widehat{\pi}
_{g}\right)  \cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(
\widehat{\beta}_{g,t,\delta}^{nev}\right)  \right)  \right]  \frac{1}{\sqrt
{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{w}_{g}^{comp,nev}\left(  W_{i}
;\widehat{\pi}_{g}\right) \\
&  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\frac{\dfrac{p_{g}\left(
X_{i};\pi_{g}^{\ast}\right)  C_{i}}{1-p_{g}\left(  X;\pi_{g}^{\ast}\right)  }
}{\mathbb{E}_{n}\left[  \dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}
_{g}\right)  C}{1-\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]
}\cdot\left(  Y_{i,t}-Y_{i,g-\delta-1}-m_{g,t,\delta}^{nev}\left(  W_{i}
;\beta_{g,t,\delta}^{\ast,nev}\right)  \right) \\
&  +\sqrt{n}\left(  \widehat{\pi}_{g}-\pi_{g}^{\ast}\right)  ^{\prime}\frac
{1}{n}\sum_{i=1}^{n}V_{i}\cdot\frac{\dfrac{C_{i}}{\left(  1-p_{g}\left(
X_{i};\bar{\pi}_{g}\right)  \right)  ^{2}}}{\mathbb{E}_{n}\left[
\dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  C}{1-\widehat{p}
_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]  }\cdot\left(  Y_{i,t}
-Y_{i,g-\delta-1}-m_{g,t,\delta}^{nev}\left(  W_{i};\beta_{g,t,\delta}
^{\ast,nev}\right)  \right)  \cdot\dot{p}_{g}\left(  X_{i};\bar{\pi}
_{g}\right) \\
&  -\sqrt{n}\left(  \widehat{\beta}_{g,t,\delta}^{nev}-\beta_{g,t,\delta
}^{\ast,nev}\right)  ^{\prime}\frac{1}{n}\sum_{i=1}^{n}V_{i}\cdot
\widehat{w}_{g}^{comp,nev}\left(  W_{i};\widehat{\pi}_{g}\right)  \cdot\dot
{m}_{g,t,\delta}^{nev}\left(  W_{i};\bar{\beta}_{g,t,\delta}^{nev}\right) \\
&  -\widehat{M}_{g,t,\delta}^{comp}\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}
\cdot\frac{\dfrac{p_{g}\left(  X_{i};\pi_{g}^{\ast}\right)  C_{i}}
{1-p_{g}\left(  X_{i};\pi_{g}^{\ast}\right)  }}{\mathbb{E}_{n}\left[
\dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  C}{1-\widehat{p}
_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]  }\\
&  -\widehat{M}_{g,t,\delta}^{comp}\sqrt{n}\left(  \widehat{\pi}_{g}-\pi
_{g}^{\ast}\right)  ^{\prime}\frac{1}{n}\sum_{i=1}^{n}V_{i}\cdot\frac
{\dfrac{C_{i}}{\left(  1-p_{g}\left(  X_{i};\bar{\pi}_{g}\right)  \right)
^{2}}}{\mathbb{E}_{n}\left[  \dfrac{\widehat{p}_{g}\left(  X;\widehat{\pi}
_{g}\right)  C}{1-\widehat{p}_{g}\left(  X;\widehat{\pi}_{g}\right)  }\right]
}\cdot\dot{p}_{g}\left(  X_{i};\bar{\pi}_{g}\right) \\
&  =\widehat{I}_{g,t,\delta}^{1,comp}+\widehat{I}_{g,t,\delta}^{2,comp}
-\widehat{I}_{g,t,\delta}^{3,comp}-\widehat{I}_{g,t,\delta}^{4,comp}
-\widehat{I}_{g,t,\delta}^{5,comp},
\end{align*}
where $\bar{\beta}_{g,t,\delta}^{nev}$ and $\bar{\pi}_{g}$ are intermediate
points that satisfies $\left\vert \bar{\beta}_{g,t,\delta}^{nev}
-\beta_{g,t,\delta}^{\ast,nev}\right\vert \leq\left\vert \widehat{\beta
}_{g,t,\delta}^{nev}-\beta_{g,t,\delta}^{\ast,nev}\right\vert $ a.s. and
$\left\vert \bar{\pi}_{g}-\pi_{g}^{\ast}\right\vert \leq\left\vert
\widehat{\pi}_{g}-\pi_{g}^{\ast}\right\vert $ a.s., respectively, and
\[
\widehat{M}_{g,t,\delta}^{comp}=\mathbb{E}_{n}\left[  \widehat{w}
_{g}^{comp,nev}\left(  \widehat{\pi}_{g}\right)  \cdot\left(  Y_{t}
-Y_{g-\delta-1}-m_{g,t,\delta}^{nev}\left(  \widehat{\beta}_{g,t,\delta}
^{nev}\right)  \right)  \right]  .
\]
From the strong law of large numbers and the fact that $V$ is mean zero, has
variance one, and is independent of $W$, it follows that
\begin{align*}
\widehat{I}_{g,t,\delta}^{1,comp}  &  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}
V_{i}\cdot w_{g}^{comp,nev}\left(  W_{i};\pi_{g}^{\ast}\right)  \cdot\left(
Y_{i,t}-Y_{i,g-\delta-1}-m_{g,t,\delta}^{nev}\left(  W_{i};\beta_{g,t,\delta
}^{\ast,nev}\right)  \right)  +o_{p^{\ast}}\left(  1\right)  ,\\
\widehat{I}_{g,t,\delta}^{3,treat}  &  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}
V_{i}\cdot w_{g}^{comp,nev}\left(  W_{i};\pi_{g}^{\ast}\right)  \cdot
\mathbb{E}\left[  w_{g}^{comp}\cdot\left(  Y_{t}-Y_{g-\delta-1}-m_{g,t,\delta
}^{nev}\left(  \beta_{g,t,\delta}^{\ast,nev}\right)  \right)  \right]
+o_{p^{\ast}}\left(  1\right)  .
\end{align*}
Similarly, from Assumptions \ref{ass:parametric} and \ref{ass:integrabilitity}
, and the strong law of large numbers, we conclude that
\[
\widehat{I}_{g,t,\delta}^{2,comp}=\widehat{I}_{g,t,\delta}^{4,comp}
=\widehat{I}_{g,t,\delta}^{5,comp}=o_{p^{\ast}}\left(  1\right)  .
\]
Now (\ref{boot:comp}) follows from combining these results. }

{\small Next, we show that
\begin{equation}
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left(  \widehat{\psi}
_{g,t}^{est,nev}(W_{i};\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta}
^{nev})-\psi_{g,t}^{est,nev}(W_{i};\pi_{g}^{\ast},\beta_{g,t,\delta}
^{\ast,nev})\right)  =o_{p^{\ast}}\left(  1\right)  . \label{boot:est}
\end{equation}
From the strong law of large numbers and Assumptions \ref{ass:parametric} and
\ref{ass:integrabilitity},
\begin{align*}
&  \frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\widehat{\psi}_{g,t}
^{est,nev}(W_{i};\widehat{\pi}_{g},\widehat{\beta}_{g,t,\delta}^{nev})\\
&  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left(  l_{g,t}^{or,nev}\left(
W_{i};\widehat{\beta}_{g,t,\delta}^{nev}\right)  ^{\prime}\cdot M_{g,t,\delta
}^{dr,nev,1}+l_{g}^{ps,nev}\left(  W_{i};\widehat{\pi}_{g}\right)  ^{\prime
}\cdot M_{g,t,\delta}^{dr,nev,2}\right)  +o_{p^{\ast}}\left(  1\right) \\
&  =\frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot l_{g,t}^{est}\left(
W_{i};\widehat{\kappa}_{g,t}^{nev}\right)  +o_{p^{\ast}}\left(  1\right)  ,
\end{align*}
where, for a generic $\kappa_{g,t}^{nev}=\left(  \pi_{g}^{\prime}
,\beta_{g,t,\delta}^{nev^{\prime}}\right)  ^{\prime},$
\[
l_{g,t}^{est}\left(  W;\kappa_{g,t}^{nev}\right)  =l_{g,t}^{or,nev}\left(
W;\beta_{g,t,\delta}^{nev}\right)  ^{\prime}\cdot M_{g,t,\delta}
^{dr,nev,1}+l_{g}^{ps,nev}\left(  W_{i};\pi_{g}\right)  ^{\prime}\cdot
M_{g,t,\delta}^{dr,nev,2}
\]
Thus, from Lemma 4.3 in \cite{Newey1994c} and Assumption \ref{ass:parametric},
it follows that
\begin{align*}
&  Var^{\ast}\left(  \frac{1}{\sqrt{n}}\sum_{i=1}^{n}V_{i}\cdot\left(
l_{g,t}^{est}\left(  W_{i};\widehat{\kappa}_{g,t,\delta}^{nev}\right)
-l_{g,t}^{est}\left(  W_{i};\kappa_{g,t,\delta}^{\ast,nev}\right)  \right)
\right) \\
&  =\frac{1}{n}\sum_{i=1}^{n}\left(  l_{g,t}^{est}\left(  W_{i}
;\widehat{\kappa}_{g,t,\delta}^{nev}\right)  -l_{g,t}^{est}\left(
W_{i};\kappa_{g,t,\delta}^{\ast,nev}\right)  \right)  ^{2}\\
&  =o_{p}\left(  1\right)  ,
\end{align*}
which, in turn, implies (\ref{boot:est}). }

{\small Taking (\ref{boot:treated}), (\ref{boot:comp}),\ and (\ref{boot:est})
together, we then establish (\ref{boot:needed}). Thus, by (\ref{eq:boot.0}),
we have
\[
\sqrt{n}\left(  \widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{\ast
,dr,nev}-\widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{dr,nev}\right)
\underset{\ast}{\overset{d}{\rightarrow}}N(0,\Sigma).
\]
}

{\small Finally, by the continuous mapping theorem, see e.g. Theorem 10.8 in
\cite{kosorok2008}, for any continuous functional $\Gamma(\cdot)$
\[
\Gamma\left(  \sqrt{n}\left(  \widehat{ATT}_{t\geq\left(  g-\delta\right)
}^{\ast,dr,nev}-\widehat{ATT}_{t\geq\left(  g-\delta\right)  }^{dr,nev}
\right)  \right)  \underset{\ast}{\overset{d}{\rightarrow}}\Gamma\left(
N(0,\Sigma)\right)  ,
\]
concluding our proof. $\square$ }

{\small We defer the proof of Theorem \ref{thm:att_rcs} to the Supplementary
Appendix. The identification results in Theorem \ref{thm:att_rcs} suggest a
simple two-step estimation procedure for the $ATT(g,t)$ with repeated
cross-section data that is analogous to the panel data case discussed in
Section \ref{sec:estimation}. The asymptotic properties of such two-step
estimators follow from analogous arguments; the details are omitted for
brevity. Likewise, we can aggregate these estimators to provide summary
measures of the causal effects like those discussed in Section \ref{sec:4}. }

